import base64,json
from pathlib import Path
from playwright.sync_api import sync_playwright
out=Path('/workspace/prisma-texture-audit')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-angle=gl-egl','--ignore-gpu-blocklist','--disable-gpu-sandbox']);page=b.new_page();page.route('**/__export_texture__',lambda r:r.fulfill(body='<html></html>',content_type='text/html'));page.goto('http://127.0.0.1:4186/__export_texture__')
 result=page.evaluate('''async()=>{const {Renderer}=await import('/renderer.js'),{newCreation,material,textureStyle}=await import('/creative-model.js');const s=newCreation();material(s,11);textureStyle(s,0);s.grounding=0;const before=JSON.stringify(s),r=new Renderer(document.createElement('canvas'));await r.drawAccumulated(s,0,128,128,{samples:2});const pixels=r.pixels(),png=r.canvas.toDataURL();await r.drawAccumulated({...s,textureWrinkles:0,textureFolds:0,textureWear:0,textureRipples:0},0,128,128,{samples:2});const smooth=r.pixels();let difference=0,lit=0;for(let i=0;i<pixels.length;i++){difference+=Math.abs(pixels[i]-smooth[i]);if(i%4<3&&pixels[i]>30)lit++;}const result={meanDifference:difference/pixels.length,lit,glError:r.gl.getError(),lost:r.gl.isContextLost(),unchangedSource:JSON.stringify(s)===before,png};r.dispose();return result;}''');b.close();(out/'texture-full-export.png').write_bytes(base64.b64decode(result.pop('png').split(',')[1]));(out/'texture-export-results.json').write_text(json.dumps(result,indent=2));print(json.dumps(result));assert result['meanDifference']>.05 and result['lit']>100 and result['glError']==0 and not result['lost'] and result['unchangedSource'],result
